import{_ as o,o as i,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.3.4 Update Client Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-4-update-client-profile/spec.md","filePath":"feature/profile/3-3-4-update-client-profile/spec.md"}'),r={name:"feature/profile/3-3-4-update-client-profile/spec.md"};function n(l,e,s,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-3-4-update-client-profile" tabindex="-1">3.3.4 Update Client Profile <a class="header-anchor" href="#_3-3-4-update-client-profile" aria-label="Permalink to &quot;3.3.4 Update Client Profile&quot;">​</a></h1><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency. See 3.3.3 <a href="./../3-3-3-view-client-profile/spec.html">spec.md</a> for the full rationale.</p><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a user creates a new Client Profile or saves edits to one of their existing Client Profiles, on the &quot;My Brand Profiles&quot; screen (<code>/client-profiles</code>).</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Any signed-in user, editing a Client Profile they own.</li><li><strong>Purpose:</strong> Let a user keep the brand information they represent up to date, or add a new brand profile. The email address cannot be set on a Client Profile — it is always the fixed identity of the owning user, read from their User account.</li><li><strong>Interface:</strong> The &quot;My Brand Profiles&quot; screen (3.3.3) in create/edit mode. Editable fields: display name (required), company, phone number, note, logo, website, industry, location, description, social links, plus brand fields (contact name, contact email, company size, Instagram URL, tax code, address, tagline, founded year, budget range). There is no email field for the owner&#39;s own identity, and no Agency selector anywhere in the form.</li><li><strong>Data Processing:</strong> The system resolves the caller&#39;s identity from the access token. For create, it inserts a new <code>client_profiles</code> row owned by the caller. For update, it looks up the profile by <code>id</code>, verifies <code>userId</code> matches the caller, writes the complete submitted field set over the record, stamps the update time, and persists. The record is never scoped to an Agency, so the update is visible wherever that profile is linked (any workspace, any Agency) at once.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Brand Profile form (<code>/client-profiles</code>, create/edit):</p><ul><li>Header: page title &quot;My Brand Profiles&quot;.</li><li>Center: the Client Profile card in create/edit mode — display name input (required), and company, phone number, note, logo, website, industry, location, description, social links, and brand-field inputs.</li><li>Buttons: Save (primary) — submits create or update; Cancel — discards the changes; Delete (edit mode only, blocked while the profile is linked to an active workspace membership).</li><li>No email field is present in the form.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> <code>displayName</code>.</li><li><strong>Input optional:</strong> <code>company</code>, <code>phone</code>, <code>note</code>, <code>logoUrl</code>, <code>website</code>, <code>industry</code>, <code>location</code>, <code>description</code>, <code>socialLinks</code>, <code>contactName</code>, <code>contactEmail</code>, <code>companySize</code>, <code>instagramUrl</code>, <code>taxCode</code>, <code>address</code>, <code>tagline</code>, <code>foundedYear</code>, <code>budgetRange</code>.</li><li><strong>System data:</strong> <code>client_profiles</code> — <code>id</code>, <code>userId</code>, <code>displayName</code>, <code>company</code>, <code>phone</code>, <code>note</code>, <code>logoUrl</code>, <code>website</code>, <code>industry</code>, <code>location</code>, <code>description</code>, <code>socialLinks</code>, plus the brand fields above, <code>createdAt</code>, <code>updatedAt</code>.</li><li><strong>Output:</strong> The complete Client Profile field set after the record is created or updated.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>Implementation note (no dedicated global BR):</strong> Create and update are separate requests (<code>POST</code>/<code>PUT</code> by <code>id</code>), not an upsert keyed by any (user, agency) pair — a Client Profile is never implicitly created from an update call.</li><li><strong>Implementation note (no dedicated global BR):</strong> The update is a full overwrite, not a partial patch — every call must submit all fields that should be kept, because fields left out are written as empty.</li><li><strong>BR-38 (reworked):</strong> A Client Profile is never scoped to a single Agency — editing it updates the one record everywhere it is linked (every workspace of every Agency the profile is used in). There is no &quot;per-Agency copy&quot; to keep in sync.</li><li><strong>BR-19:</strong> Email and role are not mutable via this action — they require separate flows. The request carries no email field for the owner&#39;s own account, so it cannot be changed through this action.</li><li><strong>Implementation note (no dedicated global BR):</strong> <code>displayName</code> is mandatory and must not be blank.</li><li><strong>Implementation note (no dedicated global BR):</strong> A Client Profile cannot be deleted while it is linked (<code>workspace_members.client_profile_id</code>) to an active workspace membership — <code>CLIENT_PROFILE_IN_USE</code>.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li><code>displayName</code> empty or blank → 400 <code>VALIDATION_ERROR</code>, Display: MSG02.</li><li>Update/delete on a profile not owned by the caller → 403 <code>CLIENT_PROFILE_NOT_OWNED</code>.</li><li>Delete while linked to an active workspace membership → 409 <code>CLIENT_PROFILE_IN_USE</code>.</li><li>Missing, expired, or invalid access token → 401 <code>UNAUTHORIZED</code>, Display: MSG22.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The user opens &quot;My Brand Profiles&quot;, fills the form (or edits an existing profile), and clicks Save.</li><li>The application submits the complete set of Client Profile fields.</li><li>The system resolves the caller&#39;s identity from the access token.</li><li>For update, the system looks up the profile by <code>id</code> and verifies ownership.</li><li>The system writes the submitted fields over the record (full overwrite for update, straight insert for create) and stamps the update time.</li><li>The system persists the record and returns the complete Client Profile field set.</li><li>The application confirms success and refreshes the list; because the profile is never Agency-scoped, the new values appear everywhere it is linked at once.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>1.a1: <code>displayName</code> submitted empty or blank → 400 <code>VALIDATION_ERROR</code>, Display: MSG02. 1.a2: The form stays open with the error shown; the user re-enters a display name and saves again.</li><li>4.a1: The profile <code>id</code> belongs to a different user → 403 <code>CLIENT_PROFILE_NOT_OWNED</code>. 4.a2: The application shows an access-denied error and returns to the list.</li><li>7.a1: An email address is submitted for the owner&#39;s own identity (BR-19) → it cannot be carried by the update request. 7.a2: The field is silently ignored; the record is saved without an email change.</li><li>Delete.a1: The profile is linked to an active workspace membership → 409 <code>CLIENT_PROFILE_IN_USE</code>. Delete.a2: The user is told to remove the profile from every workspace first, or keeps the profile.</li><li>N.a1: Missing, expired, or invalid access token at any step → 401 <code>UNAUTHORIZED</code>, toast MSG22. N.a2: The user signs in again at /login (3.2.2).</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The Client Profile holds exactly the submitted field values; fields left out are empty (full overwrite, not a partial patch).</li><li>The updated values are visible wherever the profile is currently linked, across every Agency.</li><li>Other Client Profiles owned by the same or different users are unchanged.</li></ul>',23)])])}const f=o(r,[["render",n]]);export{u as __pageData,f as default};
